struct IntegrationChecks {
 static void require(bool condition,std::source_location at=std::source_location::current()){if(!condition)throw std::runtime_error("storage assertion line "+std::to_string(at.line()));}
 static int scalar(Window& w,QString sql){QSqlQuery q(sql,w.db_);require(q.next());return q.value(0).toInt();}
 static QByteArray bytes(QString path){QFile f(path);require(f.open(QIODevice::ReadOnly));return f.readAll();}
 static void drain(Window& w){QElapsedTimer t;t.start();do{w.pumpMessages();w.flushJournal();QApplication::processEvents();if(w.pendingMessages_.empty()&&scalar(w,"SELECT count(*) FROM journal_outbox WHERE done=0")==0)return;QThread::msleep(10);}while(t.elapsed()<15000);throw std::runtime_error("queues did not drain");}
 static void configure(Window& w,QString root){w.generalCopy_->setChecked(true);w.root_->setText(root+"/general");w.selectedLogging_->setChecked(true);w.selectedLogPath_->setText(root+"/selected.txt");w.sql("INSERT OR IGNORE INTO capcodes(ric,alias,active,show_bottom,txt_enabled) VALUES(42,'Test',1,1,1)");}
 static pocsag::Message message(QString text="IDENTICAL"){return {42,0,1200,"ALPHA",text.toStdString(),0};}
 static QDateTime stamp(){return QDateTime::fromString("2026-11-05T12:00:00Z",Qt::ISODate);}
 static void locking(){QTemporaryDir dir;Window w(dir.path());configure(w,dir.path());w.sql("WITH RECURSIVE n(x) AS(VALUES(1) UNION ALL SELECT x+1 FROM n WHERE x<1024) INSERT INTO messages(timestamp,ric,type,text,baud) SELECT '2026-11-05T12:00:00+01:00',42,'ALPHA','HISTORY',1200 FROM n");w.refresh();require(w.all_->rowCount()==1024);require(w.all_->index(0,8).data().toString()=="HISTORY");
  auto lock=QSqlDatabase::addDatabase("QSQLITE","external-lock");lock.setDatabaseName(w.db_.databaseName());require(lock.open());{QSqlQuery q(lock);require(q.exec("BEGIN IMMEDIATE"));}
  QElapsedTimer elapsed;elapsed.start();for(int i=0;i<12;++i)w.received(message(),169626000,"test",stamp());require(elapsed.elapsed()<2500);require(w.pendingMessages_.size()==12&&scalar(w,"SELECT count(*) FROM messages")==1024);require(QDir(w.pendingDirectory_).entryList({"*.json"},QDir::Files).size()==12);require(w.sqliteRetries_>0);require(lock.commit());drain(w);w.refresh();require(w.all_->rowCount()==1036&&w.saved_->rowCount()==1036);auto expected=QByteArray("0000042 2026-11-05 13:00:00 IDENTICAL\r\n").repeated(12);require(bytes(dir.path()+"/general/Belgique-2026-11-05.txt")==expected&&bytes(dir.path()+"/selected.txt")==expected);require(w.pendingMessages_.empty());
  // Finished page reads leave no pinned WAL snapshot; concurrent commit remains writable.
  {QSqlQuery q(lock);require(q.exec("INSERT INTO messages(timestamp,ric,type,text,baud) VALUES('2026-11-05',42,'ALPHA','external',1200)"));}w.received(message("AFTER EXTERNAL COMMIT"),169626000,"test",stamp());drain(w);require(w.pendingMessages_.empty());
  {QSqlQuery checkpoint("PRAGMA wal_checkpoint(TRUNCATE)",lock);require(checkpoint.next()&&checkpoint.value(0).toInt()==0);}lock.close();
 }
 static void receipts(){QTemporaryDir dir;Window w(dir.path());configure(w,dir.path());w.sql("CREATE TRIGGER ack_failure BEFORE UPDATE OF done ON journal_outbox WHEN NEW.done=1 BEGIN SELECT RAISE(ABORT,'injected ACK failure'); END");for(int i=0;i<4;++i)w.received(message(),169626000,"test",stamp());w.flushJournal();auto general=dir.path()+"/general/Belgique-2026-11-05.txt";require(bytes(general).count("IDENTICAL")==1&&bytes(dir.path()+"/selected.txt").count("IDENTICAL")==1);for(int i=0;i<3;++i)w.flushJournal();require(bytes(general).count("IDENTICAL")==1);w.sql("DROP TRIGGER ack_failure");drain(w);require(bytes(general).count("IDENTICAL")==4&&bytes(dir.path()+"/selected.txt").count("IDENTICAL")==4);w.sql("UPDATE journal_outbox SET done=0");drain(w);require(bytes(general).count("IDENTICAL")==4);}
 static void restart(){QTemporaryDir dir;auto lock=QSqlDatabase::addDatabase("QSQLITE","restart-lock");QString savedEvent;{
  Window w(dir.path());configure(w,dir.path());w.saveOptions();lock.setDatabaseName(w.db_.databaseName());require(lock.open());{QSqlQuery q(lock);require(q.exec("BEGIN IMMEDIATE"));}w.received(message("RESTART"),169626000,"test",stamp());require(w.pendingMessages_.size()==1);savedEvent=QString::fromUtf8(QJsonDocument(w.pendingMessages_.front()).toJson());}
  require(lock.commit());lock.close();{Window w(dir.path());drain(w);require(scalar(w,"SELECT count(*) FROM messages")==1);require(bytes(dir.path()+"/selected.txt").count("RESTART")==1);auto o=QJsonDocument::fromJson(savedEvent.toUtf8()).object();QFile duplicate(QDir(w.pendingDirectory_).filePath(o["id"].toString()+".json"));require(duplicate.open(QIODevice::WriteOnly));duplicate.write(savedEvent.toUtf8());}
  {Window w(dir.path());drain(w);require(scalar(w,"SELECT count(*) FROM messages")==1&&bytes(dir.path()+"/selected.txt").count("RESTART")==1);}
 }
 static void routing(){QTemporaryDir dir;Window w(dir.path());configure(w,dir.path());QFile old(dir.path()+"/selected.txt");require(old.open(QIODevice::WriteOnly));old.write("OLD CONTENT\r\n");old.close();auto time=QDateTime::fromString("2026-11-05T22:59:59Z",Qt::ISODate);int expectedGeneral=0,expectedSelected=0;
  for(int flags=0;flags<4;++flags){w.generalCopy_->setChecked(flags&1);w.selectedLogging_->setChecked(flags&2);w.received(message("MATRIX"),169626000,"test",time);w.received({43,0,1200,"ALPHA","UNREGISTERED",0},169626000,"test",time);if(flags&1)expectedGeneral+=2;if(flags&2)++expectedSelected;drain(w);}
  auto general=dir.path()+"/general/Belgique-2026-11-05.txt";require(bytes(general).count("\r\n")==expectedGeneral);require(bytes(dir.path()+"/selected.txt").startsWith("OLD CONTENT\r\n")&&bytes(dir.path()+"/selected.txt").count("MATRIX")==expectedSelected&&!bytes(dir.path()+"/selected.txt").contains("UNREGISTERED"));w.generalCopy_->setChecked(true);w.selectedLogging_->setChecked(true);w.received(message("AFTER MIDNIGHT"),169626000,"test",time.addSecs(2));drain(w);require(bytes(dir.path()+"/general/Belgique-2026-11-06.txt")=="0000042 2026-11-06 00:00:01 AFTER MIDNIGHT\r\n");require(bytes(dir.path()+"/selected.txt").contains("AFTER MIDNIGHT"));
  w.sql("UPDATE capcodes SET txt_enabled=0");w.received(message("TXT OFF"),169626000,"test",time);drain(w);require(bytes(general).contains("TXT OFF")&&!bytes(dir.path()+"/selected.txt").contains("TXT OFF"));require(w.saved_->rowCount()>0);w.saveOptions();}
 static void history(){QTemporaryDir dir;Window w(dir.path());w.generalCopy_->setChecked(false);w.sql("INSERT INTO capcodes(ric,retention_days) VALUES(42,1)");w.sql("WITH RECURSIVE n(x) AS(VALUES(1) UNION ALL SELECT x+1 FROM n WHERE x<100000) INSERT INTO messages(timestamp,ric,type,text,baud) SELECT '2001-01-01T12:00:00+01:00',42,'ALPHA','history-'||x,1200 FROM n");w.refresh();require(w.all_->rowCount()==100000&&w.saved_->rowCount()==100000);require(w.all_->index(0,8).data().toString()=="history-1"&&w.all_->index(99999,8).data().toString()=="history-100000");for(int i=0;i<100;++i)w.all_->index(i*997,8).data();require(static_cast<MessageModel*>(w.all_)->cachedRows()<=4096);w.resize(1200,800);w.show();QApplication::processEvents();w.allView_->scrollToTop();QApplication::processEvents();int oldScroll=w.allView_->verticalScrollBar()->value();w.received(message("NEW BOTTOM"),169626000,"test",stamp());QApplication::processEvents();require(w.all_->rowCount()==100001&&w.all_->index(100000,8).data().toString()=="NEW BOTTOM");require(w.allView_->verticalScrollBar()->value()==oldScroll);w.allView_->scrollToBottom();QApplication::processEvents();w.received(message("FOLLOW BOTTOM"),169626000,"test",stamp());QApplication::processEvents();require(w.allView_->verticalScrollBar()->value()>=w.allView_->verticalScrollBar()->maximum()-2);require(scalar(w,"SELECT count(*) FROM messages WHERE timestamp LIKE '2001%'")==100000);}
 static void fileErrors(){QTemporaryDir dir;Window w(dir.path());configure(w,dir.path());QFile blocker(dir.path()+"/blocked");require(blocker.open(QIODevice::WriteOnly));blocker.write("KEEP");blocker.close();w.selectedLogPath_->setText(dir.path()+"/blocked/interventions.txt");for(int i=0;i<3;++i)w.received(message("DISK RETRY"),169626000,"test",stamp());w.flushJournal();require(w.all_->rowCount()==3&&w.saved_->rowCount()==3);require(scalar(w,"SELECT count(*) FROM journal_outbox WHERE done=0")==3);auto general=dir.path()+"/general/Belgique-2026-11-05.txt";require(bytes(general).count("DISK RETRY")==3);require(QFile::remove(blocker.fileName()));drain(w);require(bytes(w.selectedLogPath_->text()).count("DISK RETRY")==3&&bytes(general).count("DISK RETRY")==3);}
 static void journalDialog(){QTemporaryDir dir;Window w(dir.path());auto edit=[&](QString path,bool valid){std::exception_ptr error;QTimer dismiss;QObject::connect(&dismiss,&QTimer::timeout,[]{if(auto box=qobject_cast<QMessageBox*>(QApplication::activeModalWidget()))box->accept();});dismiss.start(10);QTimer::singleShot(0,&w,[&]{auto d=qobject_cast<QDialog*>(QApplication::activeModalWidget());try{require(d);d->findChild<QLineEdit*>("generalRoot")->setText(dir.path()+"/root with spaces");d->findChild<QCheckBox*>("generalEnabled")->setChecked(true);d->findChild<QLineEdit*>("selectedJournalPath")->setText(path);d->findChild<QCheckBox*>("selectedEnabled")->setChecked(true);d->findChild<QDialogButtonBox*>()->button(QDialogButtonBox::Save)->click();require(d->isVisible()!=valid);if(!valid){require(d->findChild<QLineEdit*>("selectedJournalPath")->text()==path);d->reject();}}catch(...){error=std::current_exception();if(d)d->reject();}});w.journal();if(error)std::rethrow_exception(error);};
  for(auto invalid:{QString("relative.txt"),dir.path()+"/NUL.txt",dir.path()+"/bad?.txt"})edit(invalid,false);QString path=dir.path()+"/Interventions existing.txt";QFile old(path);require(old.open(QIODevice::WriteOnly));old.write("PRESERVE\r\n");old.close();
#ifdef Q_OS_WIN
  auto native=QDir::toNativeSeparators(path);HANDLE locked=CreateFileW(reinterpret_cast<const wchar_t*>(native.utf16()),GENERIC_READ,FILE_SHARE_READ,nullptr,OPEN_EXISTING,FILE_ATTRIBUTE_NORMAL,nullptr);require(locked!=INVALID_HANDLE_VALUE);edit(path,false);CloseHandle(locked);
#endif
  edit(path,true);require(bytes(path)=="PRESERVE\r\n"&&w.selectedLogging_->isChecked()&&w.generalCopy_->isChecked()&&w.selectedLogPath_->text()==path);}
 static void run(){locking();receipts();restart();routing();history();fileErrors();journalDialog();}
 static void hardware(QString reportPath,int bothSeconds){QTemporaryDir dir;Window w(dir.path());configure(w,dir.path());w.show();QApplication::processEvents();QJsonArray phases;QSet<quint32> delayed;bool locked=false,arm=false;int locks=0,stalePolls=0;auto lock=QSqlDatabase::addDatabase("QSQLITE","hardware-lock");lock.setDatabaseName(w.db_.databaseName());require(lock.open());auto registerRic=[&](quint32 ric){w.sql(QString("INSERT OR IGNORE INTO capcodes(ric,alias,active,show_bottom,txt_enabled) VALUES(%1,'Test matériel',1,1,1)").arg(ric));};
  // Test configuration registers received RICs in this isolated database only.
  auto releaseLock=[&]{if(!locked)return;require(lock.commit());locked=false;for(auto ric:delayed)registerRic(ric);delayed.clear();w.pumpMessages();};
  QObject::disconnect(&w.radio_,&Receiver::frame,&w,nullptr);QObject::connect(&w.radio_,&Receiver::frame,&w,[&](pocsag::Message m,quint32 hz,QString source,QDateTime timestamp){if(locked)delayed.insert(m.ric);else registerRic(m.ric);if(arm&&!locked){QSqlQuery q(lock);require(q.exec("BEGIN IMMEDIATE"));arm=false;locked=true;++locks;QTimer::singleShot(6000,&w,releaseLock);}w.received(std::move(m),hz,source,timestamp);});w.frequency_->setValue(169.626);w.start();int totalExpectedGeneral=0,totalExpectedSelected=0;quint64 lastBytes=0;int lastCount=0;bool allGreen=true;int phaseIndex=0;
  for(auto definition:QList<QPair<int,int>>{{0,60},{1,60},{2,60},{3,bothSeconds}}){int flags=definition.first,seconds=definition.second;w.generalCopy_->setChecked(flags&1);w.selectedLogging_->setChecked(flags&2);auto beforePersisted=w.persistedFrames_;QElapsedTimer duration;duration.start();QEventLoop loop;QTimer poll;int nextProgress=60,nextLock=10;bool live=false;
   QObject::connect(&poll,&QTimer::timeout,&loop,[&]{auto elapsed=duration.elapsed();live|=w.radio_.hasLiveIq();if(elapsed>5000&&!w.radio_.hasLiveIq())++stalePolls;if(flags==3&&elapsed/1000>=nextLock&&!locked&&!arm){arm=true;nextLock+=120;}

    if(elapsed/1000>=nextProgress){std::cout<<"phase="<<phaseIndex<<" elapsed="<<elapsed/1000<<" iq_bytes="<<w.radio_.iqBytes()<<" decoded="<<w.radio_.decodedFrames()<<" stored="<<w.persistedFrames_<<" pending="<<w.pendingMessages_.size()<<std::endl;nextProgress+=60;}if(elapsed>=seconds*1000&&(flags==3||w.persistedFrames_>beforePersisted||elapsed>=180000))loop.quit();});poll.start(100);loop.exec();arm=false;releaseLock();drain(w);w.refresh();int count=scalar(w,"SELECT count(*) FROM messages"),added=count-lastCount;lastCount=count;if(flags&1)totalExpectedGeneral+=added;if(flags&2)totalExpectedSelected+=added;allGreen&=live&&w.radio_.iqBytes()>lastBytes;lastBytes=w.radio_.iqBytes();require(w.all_->rowCount()==count&&w.saved_->rowCount()==count);phases.append(QJsonObject{{"flags",flags},{"duration_seconds",int(duration.elapsed()/1000)},{"accepted_texts",added},{"iq_live",live},{"tables_match_sqlite",true}});++phaseIndex;}
  w.radio_.stop();QApplication::processEvents();drain(w);w.refresh();auto generalPath=w.generalJournalPath(QDateTime::currentDateTimeUtc());auto general=bytes(generalPath),selected=bytes(w.selectedLogPath_->text());int generalLines=general.count('\n'),selectedLines=selected.count('\n');bool exact=true;for(auto path:{generalPath,w.selectedLogPath_->text()}){QSqlQuery q(w.db_);q.prepare("SELECT line FROM journal_outbox WHERE path=? ORDER BY id");q.addBindValue(QFileInfo(path).absoluteFilePath());require(q.exec());QByteArray expected;while(q.next())expected+=q.value(0).toByteArray();q.finish();exact&=bytes(path)==expected;}
  QJsonObject report{{"frequency_hz",169626000},{"phases",phases},{"all_iq_live",allGreen},{"iq_bytes",double(w.radio_.iqBytes())},{"decoder_frames",double(w.radio_.decodedFrames())},{"measured_codewords",double(w.radio_.measuredWords())},{"rejected_codewords",double(w.radio_.rejectedWords())},{"sqlite_messages",scalar(w,"SELECT count(*) FROM messages")},{"all_table_rows",w.all_->rowCount()},{"selected_table_rows",w.saved_->rowCount()},{"general_lines",generalLines},{"selected_lines",selectedLines},{"expected_general_lines",totalExpectedGeneral},{"expected_selected_lines",totalExpectedSelected},{"journal_exact_bytes",exact},{"sqlite_lock_injections",locks},{"stale_iq_polls",stalePolls},{"sqlite_retries",double(w.sqliteRetries_)},{"pending_messages",int(w.pendingMessages_.size())},{"pending_txt",scalar(w,"SELECT count(*) FROM journal_outbox WHERE done=0")},{"red_after_stop",!w.radio_.hasLiveIq()},{"isolated_auto_registration_for_test",true}};QFile f(reportPath);require(f.open(QIODevice::WriteOnly));f.write(QJsonDocument(report).toJson());require(allGreen&&stalePolls==0&&w.sqliteRetries_>0&&exact&&generalLines==totalExpectedGeneral&&selectedLines==totalExpectedSelected&&generalLines>0&&selectedLines>0&&w.pendingMessages_.empty()&&!w.radio_.hasLiveIq());std::cout<<"PASS actual RF, both tables and two TXT journals under temporary SQLite locks"<<std::endl;
 }
};
int main(int argc,char**argv){QApplication app(argc,argv);app.setOrganizationName("POCSAG-017-Tests");app.setApplicationName("Storage");try{auto args=app.arguments();int hardware=args.indexOf("--hardware");if(hardware>=0&&hardware+1<args.size()){int seconds=1200;int option=args.indexOf("--both-seconds");if(option>=0&&option+1<args.size())seconds=args[option+1].toInt();IntegrationChecks::hardware(args[hardware+1],seconds);}else{IntegrationChecks::run();std::cout<<"PASS SQLite snapshots, durable retry/restart, TXT receipts, independent routing, midnight, 100001-row paging and scroll\n";}return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
